else:
    # fast-doubling identities, independent of the iterative reference
    def fd(k):
        if k == 0:
            return (0, 1)
        a, b = fd(k // 2)
        c = a * (2 * b - a) % M
        d = (a * a + b * b) % M
        return (d, (c + d) % M) if k % 2 else (c, d)
    print(fd(n)[0])

